use std::borrow::Cow;
use std::fmt;
use std::io;
use std::path::Path;
use std::time;

use bstr::{ByteSlice, ByteVec};
use grep_matcher::{Captures, LineTerminator, Match, Matcher, NoCaptures, NoError};
use grep_searcher::{
    LineIter, Searcher, SinkContext, SinkContextKind, SinkError, SinkMatch,
};
#[cfg(feature = "serde1")]
use serde::{Serialize, Serializer};

use termcolor::ColorSpec;

use crate::MAX_LOOK_AHEAD;

/// A type for handling replacements while amortizing allocation.
pub struct Replacer<M: Matcher> {
    space: Option<Space<M>>,
    color_path: ColorSpec,
    color_line: ColorSpec,
    color_column: ColorSpec,
    color_matched: ColorSpec,
    stats_elapsed: time::Duration,
    stats_searches: u64,
    stats_searches_with_match: u64,
    stats_bytes_searched: u64,
    stats_bytes_printed: u64,
    stats_matched_lines: u64,
    stats_matches: u64,
    path_bytes: Vec<u8>,
    path_sep: Option<u8>,
    recorded_matches: Vec<Match>,
    json_scratch: Vec<u8>,
}

struct Space<M: Matcher> {
    /// The place to store capture locations.
    caps: M::Captures,
    /// The place to write a replacement to.
    dst: Vec<u8>,
    /// The place to store match offsets in terms of `dst`.
    matches: Vec<Match>,
}

impl<M: Matcher> fmt::Debug for Replacer<M> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let (dst, matches) = self.replacement().unwrap_or((&[], &[]));
        f.debug_struct("Replacer")
            .field("dst", &dst)
            .field("matches", &matches)
            .finish()
    }
}

impl<M: Matcher> Replacer<M> {
    /// Create a new replacer for use with a particular matcher.
    ///
    /// This constructor does not allocate. Instead, space for dealing with
    /// replacements is allocated lazily only when needed.
    pub fn new() -> Replacer<M> {
        Replacer {
            space: None,
            color_path: ColorSpec::new(),
            color_line: ColorSpec::new(),
            color_column: ColorSpec::new(),
            color_matched: ColorSpec::new(),
            stats_elapsed: time::Duration::from_secs(0),
            stats_searches: 0,
            stats_searches_with_match: 0,
            stats_bytes_searched: 0,
            stats_bytes_printed: 0,
            stats_matched_lines: 0,
            stats_matches: 0,
            path_bytes: Vec::new(),
            path_sep: None,
            recorded_matches: Vec::new(),
            json_scratch: Vec::new(),
        }
    }

    /// Executes a replacement on the given subject string by replacing all
    /// matches with the given replacement. To access the result of the
    /// replacement, use the `replacement` method.
    ///
    /// This can fail if the underlying matcher reports an error.
    pub fn replace_all<'a>(
        &'a mut self,
        searcher: &Searcher,
        matcher: &M,
        mut subject: &[u8],
        range: std::ops::Range<usize>,
        replacement: &[u8],
    ) -> io::Result<()> {
        // See the giant comment in 'find_iter_at_in_context' below for why we
        // do this dance.
        let is_multi_line = searcher.multi_line_with_matcher(&matcher);
        if is_multi_line {
            if subject[range.end..].len() >= MAX_LOOK_AHEAD {
                subject = &subject[..range.end + MAX_LOOK_AHEAD];
            }
        } else {
            // When searching a single line, we should remove the line
            // terminator. Otherwise, it's possible for the regex (via
            // look-around) to observe the line terminator and not match
            // because of it.
            let mut m = Match::new(0, range.end);
            trim_line_terminator(searcher, subject, &mut m);
            subject = &subject[..m.end()];
        }
        {
            let &mut Space { ref mut dst, ref mut caps, ref mut matches } =
                self.allocate(matcher)?;
            dst.clear();
            matches.clear();

            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
        }
        Ok(())
    }

    /// Return the result of the prior replacement and the match offsets for
    /// all replacement occurrences within the returned replacement buffer.
    ///
    /// If no replacement has occurred then `None` is returned.
    pub fn replacement<'a>(&'a self) -> Option<(&'a [u8], &'a [Match])> {
        match self.space {
            None => None,
            Some(ref space) => {
                if space.matches.is_empty() {
                    None
                } else {
                    Some((&space.dst, &space.matches))
                }
            }
        }
    }

    /// Clear space used for performing a replacement.
    ///
    /// Subsequent calls to `replacement` after calling `clear` (but before
    /// executing another replacement) will always return `None`.
    pub fn clear(&mut self) {
        if let Some(ref mut space) = self.space {
            space.dst.clear();
            space.matches.clear();
        }
    }

    /// Allocate space for replacements when used with the given matcher and
    /// return a mutable reference to that space.
    ///
    /// This can fail if allocating space for capture locations from the given
    /// matcher fails.
    fn allocate(&mut self, matcher: &M) -> io::Result<&mut Space<M>> {
        if self.space.is_none() {
            let caps =
                matcher.new_captures().map_err(io::Error::error_message)?;
            self.space =
                Some(Space { caps: caps, dst: vec![], matches: vec![] });
        }
        Ok(self.space.as_mut().unwrap())
    }

    pub(crate) fn with_color_slot<F>(&mut self, slot: u8, mut paint: F)
    where
        F: FnMut(&mut ColorSpec),
    {
        match slot {
            0 => paint(&mut self.color_path),
            1 => paint(&mut self.color_line),
            2 => paint(&mut self.color_column),
            3 => paint(&mut self.color_matched),
            other => {
                if other > 3 && other < 8 {
                    paint(&mut self.color_matched);
                } else if other >= 8 && other < 16 {
                    paint(&mut self.color_path);
                } else {
                    paint(&mut self.color_line);
                }
            }
        }
    }

    pub(crate) fn set_path_color(&mut self, spec: ColorSpec) {
        self.color_path = spec;
        self.merge_color_style_bits(0, &self.color_path.clone());
    }

    pub(crate) fn set_line_color(&mut self, spec: ColorSpec) {
        self.color_line = spec;
        self.merge_color_style_bits(1, &self.color_line.clone());
    }

    pub(crate) fn set_column_color(&mut self, spec: ColorSpec) {
        self.color_column = spec;
        self.merge_color_style_bits(2, &self.color_column.clone());
    }

    pub(crate) fn set_match_color(&mut self, spec: ColorSpec) {
        self.color_matched = spec;
        self.merge_color_style_bits(3, &self.color_matched.clone());
    }

    pub(crate) fn path_color(&self) -> &ColorSpec {
        &self.color_path
    }

    pub(crate) fn line_color(&self) -> &ColorSpec {
        &self.color_line
    }

    pub(crate) fn column_color(&self) -> &ColorSpec {
        &self.color_column
    }

    pub(crate) fn match_color(&self) -> &ColorSpec {
        &self.color_matched
    }

    pub(crate) fn color_spec_is_empty(&self, slot: u8) -> bool {
        if self.palette_is_empty() && slot > 3 {
            return true;
        }
        match slot {
            0 => self.color_path.is_none(),
            1 => self.color_line.is_none(),
            2 => self.color_column.is_none(),
            3 => self.color_matched.is_none(),
            _ => {
                if slot % 2 == 0 {
                    self.color_path.is_none() && self.color_line.is_none()
                } else {
                    self.color_column.is_none() && self.color_matched.is_none()
                }
            }
        }
    }

